function renderMap(){const st=stops[state.mapStop];return frame('data-screen',`<div class="bg"></div><div class="vignette"></div><section class="map-layout"><div class="map-image glass"><img src="${photo('traverse-map.jpg')}" alt="NASA's final traverse map of Opportunity's route from Eagle Crater to Perseverance Valley"/><div class="nasa-caption" style="position:absolute;bottom:10px;left:15px">NASA/JPL-CALTECH · PIA23178 · AUTHENTIC ROUTE MAP</div></div><div class="map-side glass"><div><div class="film-tag">MISSION ANALYSIS / 02</div><h2>45.16 km on Mars.</h2><div class="narrative-text">“Sometimes I stopped for days to examine a single rock. Those stops were the reason for the journey.”</div><div class="micro" style="display:flex;gap:10px;margin-top:12px;flex-wrap:wrap"><span style="color:#aec5d9">PLANNED DRIVE: ≈1 KM</span><span class="gold">ACTUAL: 45.16 KM</span></div><div style="margin-top:15px" class="micro gold">EXPLORE THE ROUTE · SELECT A STOP</div></div><div class="map-stop-list">${stops.map((s,i)=>`<button class="map-stop ${i===state.mapStop?'active':''}" data-action="mapStop:${i}"><span class="stop-year">${s.year}</span><span>${s.title}</span></button>`).join('')}</div><div class="map-detail"><span class="micro gold">${st.tag}</span><br/><strong>${st.title}</strong> — ${st.text}</div><div class="action-row">${btn('EXAMINE A DISCOVERY →','mapNext')}${btn('VIEW FULL MAP ⤢','openMapSource','outline slim')}</div></div></section>`,{label:'OPPORTUNITY / THE LONG JOURNEY',source:'Historical route: NASA/JPL-Caltech PIA23178 · map image provided by player'});}
const speakerInline=s=>`<span class="speaker-inline">${s==='PLAYER'?nameIcon():opportunityIcon()}<strong>${s==='PLAYER'?playerLabel():s}:</strong></span>`;
const observationChoices=[['There are tiny round formations everywhere.','round'],['They stand out from the surrounding rock.','different'],['How did these form?','formed']];
const observationReplies={round:'Those rounded mineral spheres were nicknamed “blueberries.” Their size and abundance drew immediate attention.',different:'Their chemistry was important too. Measurements indicated that the spheres contained hematite, an iron-bearing mineral.',formed:'That was the scientific question. The spheres and the rock around them helped the mission team investigate how liquid water affected this ancient environment.'};
function renderInspect(){const stage=state.inspectStep;return frame('inspect-screen',`<div class="inspect-bg"></div><section class="inspect-layout"><div class="inspect-photo glass" id="inspect-photo"><img id="inspect-image" src="${photo(state.photoZoom?'berries-closeup.jpg':'berries.jpg')}" alt="NASA's Opportunity Berry Bowl science photograph showing round hematite-rich features in Martian rock" style="transform:scale(${state.photoZoom?1.7:1})"/><div class="photo-crosshair"></div><div class="inspect-controls">${iconbtn('zoom','photoZoom','Zoom photograph')}</div><span class="photo-caption">NASA/JPL/CORNELL · OPPORTUNITY · EAGLE CRATER · 2004</span></div><div class="inspect-aside glass"><span class="film-tag">MISSION DISCOVERY / 01</span><h2>Something in the rocks.</h2>${stage===0?`<p>${speakerInline('OPPORTUNITY')} “Look closely. What do you notice?”</p><p>Examine the image using the magnifier. Then select an observation. There is no wrong choice; each opens a different explanation.</p><div class="choice-list">${observationChoices.map(([l,id])=>`<button class="choice" data-action="observe:${id}">${l}</button>`).join('')}</div>`:stage===1?`<div class="discovery-line">${observationReplies[state.inspectAnswer]}</div><p>${speakerInline('OPPORTUNITY')} “The spheres were rich in hematite. Studying them alongside the surrounding rocks provided strong evidence that liquid water had affected this place.”</p>${btn('CONTINUE →','inspectNext')}`:stage===2?`<p>${speakerInline('PLAYER')} “So Mars used to have water?”</p><p>${speakerInline('OPPORTUNITY')} “Yes. The rocks showed that at least some places on Mars were wet long ago.”</p><p>${speakerInline('PLAYER')} “Did you find life?”</p>${btn('HEAR THE ANSWER →','inspectNext')}`:stage===3?`<div class="discovery-line">${speakerInline('OPPORTUNITY')} “No. Evidence of water is not evidence of life. My instruments were designed to study rocks, soil and their history. Those are different questions.”</div><p>You've examined authentic mission evidence. Save the image to your Mission Gallery.</p>${btn('SAVE PHOTOGRAPH ↗','collectBerry')}`:`<div class="discovery-line">✓ PHOTO SAVED TO GALLERY</div><p>Martian Blueberries · Eagle Crater · March 2004</p><div class="action-row">${btn('OPEN GALLERY ↗','gallery')}${btn('RETURN TO OPPORTUNITY →','inspectFinish','outline')}</div>`}</div></section>`,{label:'OPPORTUNITY / INSTRUMENTS & EVIDENCE',source:'Real NASA rover photograph · PIA05634 (Berry Bowl) · scientific interpretation credited to NASA'});}
function renderGallery(){return frame('gallery-screen',`<div class="bg"></div><div class="gallery-wrap"><div class="gallery-top"><div><span class="film-tag">ARCHIVE / PHOTOGRAPHIC RECORDS</span><h2>Mission Gallery<span style="color:#dfbd85">.</span></h2><div class="narrative-text">Photographs Opportunity captured and sent home. Every image records part of a real scientific journey.</div></div><div class="action-row"><span class="micro gold">${state.saved.length} OF ${galleryItems.length} COLLECTED</span>${btn('CLOSE GALLERY ×','galleryClose','outline slim')}</div></div><div class="gallery-grid">${galleryItems.map(item=>{let unlocked=state.saved.includes(item.id);return `<button class="gallery-card ${unlocked?'':'locked'}" data-action="galleryItem:${item.id}" aria-label="${unlocked?'View':'Locked'} ${item.title}"><img src="${photo(item.file)}" alt="${item.title}"/>${unlocked?'':`<div class="lock-mark">◇</div>`}<div class="content"><span class="micro ${unlocked?'gold':'muted'}">${unlocked?'✓ SAVED TO ARCHIVE':'NOT YET COLLECTED'}</span><h3>${unlocked?item.title:'Undiscovered record'}</h3><p>${unlocked?`${item.place} · ${item.date}`:item.unlock}</p></div></button>`}).join('')}</div></div>`,{label:'ARCHIVE / GALLERY'});}
const returnDialogue=[
 {speaker:'PLAYER',text:'You took all of these photographs?'},
 {speaker:'OPPORTUNITY',text:'My cameras did. The images traveled to Earth, where scientists examined them alongside measurements from my other instruments.'},
 {speaker:'PLAYER',text:'And you kept traveling?'},
 {speaker:'OPPORTUNITY',text:'Yes. Eagle Crater was only the beginning. I crossed plains, investigated larger craters, and reached places beyond my original ninety-sol plan.'},
 {speaker:'OPPORTUNITY',text:'There is a better way to explain how the journey unfolded. It starts with the day I landed.'}
];
function renderReturn(){let d=returnDialogue[state.returnIndex];let last=state.returnIndex>=returnDialogue.length-1;return frame('scene-rover',`<div class="bg"></div><div class="id-reveal"><span class="micro gold">MARS EXPLORATION ROVER</span><h2>OPPORTUNITY</h2><p>MISSION MEMORY / CONTINUED</p></div><section class="glass dialogue-box">${speakerLine(d.speaker)}<div class="dialogue-copy">${d.text}</div><div class="dialogue-control"><span class="micro muted">${state.returnIndex+1} / ${returnDialogue.length}</span>${btn(last?'OPEN MISSION TIMELINE →':'CONTINUE ↓','returnNext',last?'':'ghost slim')}</div></section>`,{label:'PERSEVERANCE VALLEY / ARCHIVE RETURN',source:'Cinematic reconstruction · dialogue based on verified NASA mission history'});}
const timelineItems=[
 {year:'2004',title:'Landing Day',copy:'Opportunity landed in Eagle Crater on January 25, 2004 UTC. Its first panoramas revealed exposed rock only a short drive away. A ninety-sol mission was beginning.',img:'first-panorama.jpg',note:'Real NASA panorama from Eagle Crater',unlock:null},
 {year:'2004',title:'Searching the Rocks',copy:'The small spheres nicknamed “blueberries,” the surrounding sedimentary layers, and measurements of minerals helped establish evidence of ancient water.',img:'berries.jpg',note:'Real NASA Berry Bowl photograph',unlock:'berries'},
 {year:'2005',title:'A Trail Across the Plains',copy:'Opportunity kept driving beyond the original mission. In January 2005 it photographed the tracks it left behind on Meridiani Planum.',img:'tracks.jpg',note:'Real NASA wheel-track photograph',unlock:'tracks'},
 {year:'2006',title:'Victoria Crater',copy:'Opportunity examined the layered cliffs of a large impact crater, extending its geological investigation far beyond Eagle Crater.',img:'victoria.jpg',note:'Real NASA Victoria Crater panorama',unlock:'victoria'},
 {year:'2011',title:'Endeavour Crater',copy:'After years of travel, the rover reached Endeavour Crater. Exploring the crater rim opened access to older and different geological materials.',img:'panorama-legacy.webp',note:'Mission location; archive illustration uses a later panorama',unlock:null},
 {year:'2018',title:'The Last Signal',copy:'A planet-encircling dust storm reduced sunlight reaching the rover. Opportunity last communicated on June 10, 2018. NASA officially concluded the mission in February 2019.',img:'panorama-legacy.webp',note:'Actual final-location panorama; archive preview in this package',unlock:null}
];
function renderTimeline(){const p=timelineItems[state.timelineStop];return frame('timeline-screen',`<div class="bg"></div><div class="vignette"></div><div class="timeline-head"><span class="film-tag">OPPORTUNITY / MISSION MEMORY</span><h2>Every kilometer, a new question.</h2><p class="narrative-text">Select a year to revisit a milestone. Each photograph is a piece of the real mission record.</p></div><div class="timeline-rail">${timelineItems.map((s,i)=>`<button class="timeline-point ${i===state.timelineStop?'active':''}" data-action="timelineStop:${i}" aria-label="${s.year}, ${s.title}"><span>${s.year}</span></button>`).join('')}</div><section class="timeline-panel glass"><img src="${photo(p.img)}" alt="NASA mission photograph illustrating ${p.title}"/><div><span class="micro gold">${p.year} · ARCHIVE RECORD ${state.timelineStop+1} / ${timelineItems.length}</span><h3>${p.title}</h3><p>${p.copy}</p><div class="action-row">${btn('PREVIOUS','timelinePrev','ghost slim',state.timelineStop===0?'disabled':'')}${state.timelineStop===timelineItems.length-1?btn('COMPLETE CHAPTER →','timelineFinish',''):btn('NEXT MEMORY →','timelineNext','outline slim')}</div></div></section>`,{label:'OPPORTUNITY / MISSION TIMELINE',source:p.note+' · Historical facts sourced from NASA/JPL'});}
const goodbyeDialogue=[
 {speaker:'OPPORTUNITY',text:'Before you go, take another look at the valley. This was only one stop in a journey that lasted almost fifteen years.'},
 {speaker:'OPPORTUNITY',text:'The photographs and mission records will still be here whenever you want to return, '+ 'EXPLORER_NAME'+'. Until next time.'}
];
function renderGoodbye(){const d=goodbyeDialogue[state.goodbyeIndex],last=state.goodbyeIndex===goodbyeDialogue.length-1;return frame('scene-rover',`<div class="bg"></div><div class="vignette"></div><section class="glass dialogue-box">${speakerLine(d.speaker)}<div class="dialogue-copy">${d.text.replace('EXPLORER_NAME',playerLabel())}</div><div class="dialogue-control">${btn(last?'RETURN TO SIGNALS →':'CONTINUE ↓','goodbyeNext',last?'':'ghost slim')}</div></section>`,{label:'PERSEVERANCE VALLEY / FAREWELL',source:'Fictional archive conversation'});}
function renderEnd(){return frame('end-screen',`<div class="bg"></div><div class="vignette"></div><div class="end-center"><span class="film-tag">MISSION ARCHIVE RESTORED</span><h2>Opportunity<span class="gold">.</span></h2><div class="micro gold">JANUARY 2004 — JUNE 2018</div><p>A ninety-sol assignment became nearly fifteen years of exploration. Across 45.16 kilometers, the photographs and measurements sent from Mars helped change what we know about the planet's watery past.</p><p>Opportunity's last signal is part of the historical record. Its discoveries remain part of ours.</p><p class="micro gold">${state.saved.length} PHOTOGRAPHS COLLECTED IN YOUR GALLERY</p><div class="end-actions">${btn('OPEN MISSION GALLERY ↗','gallery')}${btn('RETURN TO SIGNALS →','signalsAgain','outline')}</div></div>`,{label:'CHAPTER COMPLETE / OPPORTUNITY',source:'Opportunity mission history · NASA / JPL-Caltech · cinematic retelling'});}
function postRender(){const s=state.scene;window.addEventListener('keydown',keyControls);/* Intro advances ONLY on NEXT, never on a timer. */
if(s==='dark'){playFx('signal');later(()=>{state.transmitIndex=0;goto('transmission')},2400)}
if(s==='transmission'&&state.transmitIndex<4){if(state.transmitIndex===0)playFx('signal');later(()=>{if(state.scene==='transmission'){state.transmitIndex+=1;render()}},state.transmitIndex===3?3400:3100)}
if(s==='signals'&&state.splitting){later(()=>{const el=$('.signals-screen');el?.classList.remove('splitting');state.splitting=false},1500)}
if(s==='travel'){travelPaused=false;if(state.travelProgress<100)beginTravel();createStreaks()}
if(s==='arrival'&&state.scanCount<scanRows.length){if(state.scanCount===0)playFx('scan');later(()=>{if(state.scene==='arrival'){state.scanCount++;render()}},state.scanCount===0?1100:570)}
if(s==='look'){setLookPosition(state.lookPos);lookDragInstall()}
if(s==='duration'){later(()=>animateDuration(),240)}
if(s==='timeline'){const el=document.querySelector('.timeline-point.active');el?.scrollIntoView?.({block:'nearest',inline:'nearest'});}
}
function nextIntro(){if(state.introIndex>=introGroups.length-1){state.nameDraft=state.playerName||'';goto('name');return}cleanup();state.introIndex++;playFx('dialogue');render()}
function beginTravel(){travelStart=performance.now()-state.travelProgress/100*26000;let last=0;function loop(now){if(state.scene!=='travel')return;if(!travelPaused){state.travelProgress=Math.min(100,(now-travelStart)/26000*100);if(now-last>40){last=now;let p=state.travelProgress;const bar=$('#travel-fill'),dot=$('#travel-dot'),count=$('#travel-time'),percent=$('#travel-percent'),planet=$('.mars-planet');if(bar)bar.style.width=p+'%';if(dot)dot.style.left=p+'%';if(percent)percent.textContent=Math.floor(p)+'%';if(count)count.textContent=Math.round(202*p/100)+' EARTH DAYS';if(planet){if(p>=96){planet.className='mars-planet close'}else if(p>=75){planet.className='mars-planet near'}else planet.className='mars-planet';}if(p>=100){state.travelProgress=100;playFx('riser');render();return}}}raf=requestAnimationFrame(loop)}raf=requestAnimationFrame(loop)}
function createStreaks(){let container=$('#stars-generated');if(!container)return;let f=document.createDocumentFragment();for(let i=0;i<75;i++){let d=document.createElement('i');d.className='streak';d.style.cssText=`top:${Math.random()*100}%;left:${Math.random()*100}%;width:${15+Math.random()*115}px;--speed:${.55+Math.random()*2.5}s;--delay:-${Math.random()*3}s;opacity:${.08+Math.random()*.65}`;f.append(d)}container.append(f)}
function animateDuration(){const bar=$('#duration-bar'),metric=$('#duration-metric');if(!bar||!metric)return;const start=performance.now();function step(now){if(state.scene!=='duration')return;let t=Math.min(1,(now-start)/3200),e=1-Math.pow(1-t,3);bar.style.width=(e*100)+'%';metric.textContent=Math.round(90+(5111-90)*e).toLocaleString('en-US');if(t<1)raf=requestAnimationFrame(step)}raf=requestAnimationFrame(step)}
let dragging=false,startX=0,startPos=0,dragged=false;
function limit(v){return Math.max(0,Math.min(1,v))}
function setLookPosition(v){state.lookPos=limit(v);const el=$('#look-back');if(el){let screen=window.innerWidth;let bw=screen*(window.innerWidth<500?2.25:1.8);el.style.width=bw+'px';el.style.transform=`translateX(${-state.lookPos*(bw-screen)}px)`;}const ready=state.lookPos>.58;if(ready&&!state.found){state.found=true;playFx('signal');later(()=>{if(state.scene==='look'){render();toast('AN UNKNOWN SIGNAL IS NEARBY')}},550)}else if(state.found){const act=$('.look-action');if(act)act.style.display='block'}const inst=$('#look-instructions');if(inst&&state.lookPos>.03)inst.textContent=ready?'SIGNAL SOURCE DETECTED':'KEEP LOOKING';}
function lookDragInstall(){const area=$('#look-scene');if(!area)return;area.addEventListener('pointerdown',e=>{dragging=true;startX=e.clientX;startPos=state.lookPos;dragged=false;area.setPointerCapture?.(e.pointerId);});area.addEventListener('pointermove',e=>{if(!dragging)return;let change=(startX-e.clientX)/Math.max(250,innerWidth*.85);if(Math.abs(e.clientX-startX)>5)dragged=true;setLookPosition(startPos+change)});area.addEventListener('pointerup',()=>{dragging=false});area.addEventListener('pointercancel',()=>{dragging=false});area.addEventListener('wheel',e=>{e.preventDefault();setLookPosition(state.lookPos+e.deltaY*.001)}, {passive:false});}
function dragMove(){}function dragEnd(){}
function keyControls(e){if(overlayMode==='settings'||overlayMode==='lightbox'){if(e.key==='Escape')closeOverlay();return}if(e.key==='Escape'&&state.scene==='gallery'){returnGallery();return}if(e.key==='ArrowRight'&&state.scene==='look'){setLookPosition(state.lookPos+.13);e.preventDefault()}else if(e.key==='ArrowLeft'&&state.scene==='look'){setLookPosition(state.lookPos-.13);e.preventDefault()}else if(e.key===' '&&['intro','transmission','conversation','return'].includes(state.scene)){e.preventDefault();if(state.scene==='intro')nextIntro();else if(state.scene==='conversation'&&!dialogueState().choices)dialogueNext();else if(state.scene==='return')returnNext();}}
function dialogueNext(){if(dialogueState().choices)return;state.dialogueIndex++;playFx('dialogue');if(state.dialogueIndex>=dialogueTotal())goto('duration');else render()}
function returnNext(){if(state.returnIndex>=returnDialogue.length-1){state.timelineStop=0;goto('timeline');return}state.returnIndex++;playFx('dialogue');render()}
function flyToGallery(file){if(state.reduced)return;const target=$('.top-actions [data-action=\"gallery\"]');const from=$('.inspect-photo');if(!target||!from)return;const a=from.getBoundingClientRect(),b=target.getBoundingClientRect();const el=document.createElement('img');el.src=photo(file);el.style.cssText=`position:fixed;left:${a.left+a.width*.5-75}px;top:${a.top+a.height*.5-48}px;width:150px;height:96px;object-fit:cover;border:2px solid #eed29c;box-shadow:0 0 50px #e9bc7d77;pointer-events:none;z-index:200;`;document.body.append(el);const dx=b.left+b.width/2-(a.left+a.width/2),dy=b.top+b.height/2-(a.top+a.height/2);const anim=el.animate([{transform:'translate(0,0) scale(1)',opacity:1},{transform:`translate(${dx}px,${dy}px) scale(.12)`,opacity:.15}],{duration:850,easing:'cubic-bezier(.2,.65,.2,1)',fill:'forwards'});anim.onfinish=()=>el.remove();}
function collect(item){if(!state.saved.includes(item)){state.saved.push(item);save();playFx('save');toast('✓ PHOTOGRAPH SAVED TO MISSION GALLERY')}}
function openGallery(){if(state.scene!=='gallery')state.galleryFrom=state.scene;goto('gallery')}
function returnGallery(){let target=state.galleryFrom||'return';if(target==='inspect'&&state.inspectStep<4)target='inspect';goto(target)}
function handleAction(str,button){const [action,value]=str.split(':');switch(action){
case 'enableSound':activateAudio();state.muted=false;save();syncSound();render();break;
case 'nameKey':state.nameDraft=(state.nameDraft||'').slice(0,15)+value;render();$('#player-name')?.focus();break;
case 'nameDelete':state.nameDraft=(state.nameDraft||'').slice(0,-1);render();$('#player-name')?.focus();break;
case 'nameSpace':state.nameDraft=(state.nameDraft||'').slice(0,15)+' ';render();$('#player-name')?.focus();break;
case 'nameSkip':state.playerName='Explorer';save();goto('dark');break;
case 'nameConfirm':{const val=($('#player-name')?.value||state.nameDraft||'').trim().replace(/[^\p{L}\p{N} _-]/gu,'').slice(0,16);state.playerName=val||'Explorer';save();goto('dark');break}
case 'start':activateAudio();state.introIndex=0;goto('intro');break;
case 'introNext':nextIntro();break;
case 'skipIntro':state.nameDraft=state.playerName||'';goto('name');break;
case 'answer':state.splitting=true;goto('signals');playFx('signal');break;
case 'signal':state.signalOpen=Number(value);playFx('signal');render();break;
case 'signalClose':state.signalOpen=null;render();break;
case 'chooseOpportunity':state.signalOpen=null;state.travelProgress=0;playFx('riser');goto('travel');break;
case 'startExploring':state.scanCount=0;goto('arrival');break;
case 'scanNext':state.lookPos=0;state.found=false;goto('look');break;
case 'panLeft':setLookPosition(state.lookPos-.14);break;
case 'panRight':setLookPosition(state.lookPos+.14);break;
case 'contact':state.dialogueIndex=0;state.dialogueBranch=null;goto('conversation');playFx('signal');break;
case 'dialogueNext':dialogueNext();break;
case 'branch':state.dialogueBranch=value;state.dialogueIndex=dialogueRoot.length;playFx('dialogue');render();break;
case 'durationNext':state.bridgeIndex=0;goto('bridge');break;
case 'bridgeNext':if(state.bridgeIndex<bridgeDialogue.length-1){state.bridgeIndex++;render();playFx('dialogue')}else{state.mapStop=0;goto('map')}break;
case 'mapStop':state.mapStop=Number(value);playFx('dialogue');render();break;
case 'openMapSource':openLocalMap();break;
case 'mapNext':state.inspectStep=0;state.inspectAnswer=null;state.photoZoom=false;goto('inspect');break;
case 'observe':state.inspectAnswer=value;state.inspectStep=1;playFx('dialogue');render();break;
case 'inspectNext':state.inspectStep++;render();break;
case 'photoZoom':state.photoZoom=!state.photoZoom;render();break;
case 'collectBerry':flyToGallery('berries.jpg');collect('berries');state.inspectStep=4;render();break;
case 'inspectFinish':state.returnIndex=0;goto('return');break;
case 'gallery':openGallery();break;
case 'galleryClose':returnGallery();break;
case 'galleryItem':{let item=galleryItems.find(x=>x.id===value);if(!item)return;if(!state.saved.includes(item.id)){toast('THIS PHOTO HAS NOT BEEN DISCOVERED YET');return}showLightbox(item);break}
case 'returnNext':returnNext();break;
case 'timelineStop':state.timelineStop=Number(value);const s=timelineItems[state.timelineStop];if(s.unlock&&s.unlock!=='berries')collect(s.unlock);playFx('dialogue');render();break;
case 'timelinePrev':state.timelineStop=Math.max(0,state.timelineStop-1);render();break;
case 'timelineNext':state.timelineStop=Math.min(timelineItems.length-1,state.timelineStop+1);{const s=timelineItems[state.timelineStop];if(s.unlock)collect(s.unlock)}render();break;
case 'timelineFinish':state.completed=true;save();goto('end');break;
case 'signalsAgain':state.goodbyeIndex=0;goto('goodbye');break;
case 'goodbyeNext':if(state.goodbyeIndex<goodbyeDialogue.length-1){state.goodbyeIndex++;render();playFx('dialogue')}else{state.signalOpen=null;goto('signals')}break;
case 'settings':showSettings();break;
case 'mute':state.muted=!state.muted;save();syncSound();const toggle=button; if(toggle){toggle.innerHTML=ico(state.muted?'mute':'sound');toggle.setAttribute('aria-label',state.muted?'Unmute':'Mute')}break;
case 'fullscreen':if(document.fullscreenElement)document.exitFullscreen?.();else document.documentElement.requestFullscreen?.();break;
case 'reset':{if(confirm('Reset your collected photographs and chapter completion?')){state.saved=[];state.completed=false;save();closeOverlay();goto('title')}break}
case 'lightboxClose':closeOverlay();break;
case 'lightboxNext':{const current=overlay.dataset.item;const list=galleryItems.filter(x=>state.saved.includes(x.id));const idx=list.findIndex(x=>x.id===current);showLightbox(list[(idx+1)%list.length]);break}
case 'lightboxPrev':{const current=overlay.dataset.item;const list=galleryItems.filter(x=>state.saved.includes(x.id));const idx=list.findIndex(x=>x.id===current);showLightbox(list[(idx-1+list.length)%list.length]);break}
case 'lightboxSource':{const current=overlay.dataset.item;const item=galleryItems.find(x=>x.id===current);if(item)window.open(item.source,'_blank','noopener');break}
case 'credits':showCredits();break;
}}
function openLocalMap(){overlayMode='map';overlay.innerHTML=`<div class="map-lightbox" role="dialog" aria-modal="true" aria-label="NASA Opportunity route map"><button class="icon-btn map-lightbox-close" data-action="lightboxClose" aria-label="Close map">${ico('close')}</button><img src="${photo('traverse-map.jpg')}" alt="Opportunity's original NASA traverse map"><div class="micro gold map-lightbox-credit">NASA/JPL-CALTECH · OPPORTUNITY FINAL TRAVERSE MAP · PIA23178</div></div>`;}
function closeOverlay(){overlay.innerHTML='';overlay.dataset.item='';overlayMode=null;}
function showSettings(){overlayMode='settings';overlay.innerHTML=`<div class="settings-layer"><section class="settings-modal glass" role="dialog" aria-modal="true" aria-label="Game settings"><span class="micro gold">MIRA QUEST / PREFERENCES</span><h2>Settings</h2><div class="settings-row"><span>Sound enabled</span><input id="settings-sound" type="checkbox" ${state.muted?'':'checked'}></div><div class="settings-row"><span>Sound volume</span><input id="settings-volume" type="range" min="0" max="1" step="0.01" value="${state.volume}"></div><div class="settings-row"><span>Reduced motion</span><input id="settings-motion" type="checkbox" ${state.reduced?'checked':''}></div><div class="settings-row"><span>Fullscreen experience</span>${btn('TOGGLE','fullscreen','outline slim')}</div><div class="settings-row"><span>Historical sources & disclosures</span>${btn('VIEW','credits','outline slim')}</div><div style="display:flex;justify-content:space-between;margin-top:25px">${btn('RESET PROGRESS','reset','ghost slim')}${btn('RETURN TO GAME →','lightboxClose','')}</div></section></div>`;$('#settings-sound').addEventListener('change',e=>{state.muted=!e.target.checked;save();syncSound()});$('#settings-volume').addEventListener('input',e=>{state.volume=Number(e.target.value);save();syncSound()});$('#settings-motion').addEventListener('change',e=>{state.reduced=e.target.checked;document.body.classList.toggle('reduce-motion',state.reduced);save()});}
function showCredits(){overlayMode='settings';overlay.innerHTML=`<div class="settings-layer"><section class="settings-modal glass" style="width:min(700px,95vw);max-height:85vh;overflow:auto" role="dialog" aria-modal="true" aria-label="Source credits"><span class="micro gold">MISSION RECORDS / PROVENANCE</span><h2>Sources & disclosures</h2><p class="narrative-text">Authentic scientific images in the Mission Gallery were supplied by the project owner and originate from NASA/JPL mission archives. Exterior Opportunity scenes, the title artwork, starfield, and travel imagery are cinematic AI-generated reconstructions, not documentary photographs. The talking rover, player travel, and interface signals are fictional storytelling devices.</p><p class="narrative-text">NASA mission facts: landed January 25, 2004 UTC; last contact June 10, 2018; 90-sol original mission; 5,111 sols at last contact; 45.16 km traversed; Endeavour Crater and Perseverance Valley final location. The mission officially ended in February 2019.</p><p class="narrative-text">Generated images: OpenAI image-generation tooling. Audio: supplied by the project owner; confirm individual licenses before publication. Code: created with OpenAI assistance and reviewed for intended interaction. Fonts: Google Fonts loaded from public CSS; fallback fonts are included through the browser.</p><p class="narrative-text">NASA original sources: <a href="${sourceLinks.panorama}" target="_blank">Final panorama</a>, <a href="${sourceLinks.map}" target="_blank">Traverse map</a>, <a href="${sourceLinks.berries}" target="_blank">Berry Bowl</a>, <a href="${sourceLinks.tracks}" target="_blank">Wheel tracks</a>, <a href="${sourceLinks.victoria}" target="_blank">Victoria Crater</a>.</p><p class="micro muted">AI-ASSISTED VISUALS REQUIRE VISIBLE WATERMARKS AND DISCLOSURE FOR THE EVENT AS ADVISED BY ITS ORGANIZER. The source note on game scenes provides a working visual designation.</p>${btn('CLOSE ×','lightboxClose')}</section></div>`}
function showLightbox(item){overlayMode='lightbox';overlay.dataset.item=item.id;overlay.innerHTML=`<div class="photo-lightbox" role="dialog" aria-modal="true" aria-label="${item.title}"><button class="icon-btn lightbox-close" data-action="lightboxClose" aria-label="Close photograph">${ico('close')}</button><img id="lightbox-img" src="${photo(item.file)}" alt="${item.title}, real NASA Opportunity photograph" /><div class="lightbox-info"><span class="micro gold">MISSION GALLERY / NASA PHOTOGRAPH</span><h2>${item.title}</h2><div class="micro muted">${item.place.toUpperCase()} · ${item.date.toUpperCase()} · ${item.instrument.toUpperCase()}</div><p>${item.description}</p><div class="lightbox-actions">${btn('← PREVIOUS','lightboxPrev','outline slim')}${btn('NASA SOURCE ↗','lightboxSource','outline slim')}${btn('NEXT →','lightboxNext','outline slim')}</div></div></div>`;let pic=$('#lightbox-img'),scale=1;pic.addEventListener('click',()=>{scale=scale===1?1.6:1;pic.style.transform=`scale(${scale})`})}
game.addEventListener('input',e=>{if(e.target.id==='player-name')state.nameDraft=e.target.value.slice(0,16)});
game.addEventListener('keydown',e=>{if(e.target.id==='player-name'&&e.key==='Enter'){e.preventDefault();handleAction('nameConfirm')}});
game.addEventListener('click',e=>{const action=e.target.closest('[data-action]');if(action)handleAction(action.dataset.action,action);});
overlay.addEventListener('click',e=>{const action=e.target.closest('[data-action]');if(action)handleAction(action.dataset.action,action);else if(e.target.classList.contains('settings-layer'))closeOverlay()});
window.addEventListener('resize',()=>{if(state.scene==='look')setLookPosition(state.lookPos)});
document.body.classList.toggle('reduce-motion',state.reduced);
document.addEventListener('pointerdown',()=>{if(audioUnlocked&&!state.muted)syncSound()},{passive:true});
document.addEventListener('visibilitychange',()=>{if(!document.hidden&&audioUnlocked&&!state.muted)syncSound()});
render();
